function* bubble(a) {
  var n = a.length;
  for (var i = 0; i < n - 1; i++) {
    for (var j = 0; j < n - 1 - i; j++) {
      yield { type: "compare", i: j, j: j + 1 };
      if (a[j] > a[j + 1]) {
        var t = a[j];
        a[j] = a[j + 1];
        a[j + 1] = t;
        yield { type: "swap", i: j, j: j + 1 };
      }
    }
  }
}

function* insertion(a) {
  var n = a.length;
  for (var i = 1; i < n; i++) {
    var key = a[i];
    var j = i - 1;
    while (j >= 0) {
      yield { type: "compare", i: j, j: j + 1 };
      if (a[j] > key) {
        a[j + 1] = a[j];
        j--;
        yield { type: "move", i: j + 1 };
      } else {
        break;
      }
    }
    a[j + 1] = key;
  }
}

function* quick(a) {
  var n = a.length;
  function* part(lo, hi) {
    var pivot = a[hi];
    var i = lo - 1;
    for (var k = lo; k < hi; k++) {
      yield { type: "compare", i: k, j: hi };
      if (a[k] < pivot) {
        i++;
        if (i !== k) {
          var t = a[i];
          a[i] = a[k];
          a[k] = t;
          yield { type: "swap", i: i, j: k };
        }
      }
